  "preferred_configuration": {
    "prize_parts": [
      {
        "ballot_id": "B001",
        "laureates": [
          "Hidetoshi Katori",
          "Jun Ye"
        ],
        "citation": "For the invention and experimental realization of optical lattice clocks."
      }
    ]
  },
  "alternatives": [
    "B049",
    "B005"
  ],
  "statement": {
    "case_for": "Optical lattice clocks are a major, experimentally verified advance in precision measurement. By controlling atoms in an optical lattice and measuring their transitions with extraordinary accuracy, they have established a durable new clock method and enabled demanding tests of fundamental physics. Katori's clock concept and Ye's experimental advances are complementary contributions to that achievement, with independent development and continued realization across laboratories supporting its maturity.",
    "case_against": "The main reservation is the boundary of the award: the original clock concept and its realization must be distinguished from the wider progress in optical frequency metrology and later technical improvements. The record should confirm that the proposed pair captures the original contributions without treating subsequent community-wide advances as theirs alone.",
    "responses": [
      {
        "member_id": "eriksson-olle",
        "point": "Eriksson ranks giant tunnel magnetoresistance first, citing its mature physical basis and importance to magnetic storage, while noting that the scope must distinguish it from giant magnetoresistance and define the credit among experimentalists and theorists.",
        "response": "I agree that the effect is mature and that Yuasa, Parkin, and Butler represent important complementary experimental and theoretical contributions. The distinction from giant magnetoresistance is essential to a defensible citation. I still place the clock achievement ahead because its core invention and independent experimental development appear more compactly identifiable, while the TMR attribution depends on resolving both the boundary with GMR and the roles across separate demonstrations and theory."
      },
      {
        "member_id": "johansson-goran",
        "point": "Johansson argues that circuit QED established an experimentally controlled regime of light–matter interaction, with Blais's theoretical architecture and Wallraff's and Schoelkopf's experimental work, while noting the broader community's role and the boundary with superconducting quantum computing.",
        "response": "That is a strong case for a verified platform whose basic phenomena have been reproduced widely. I would keep the citation narrowly on circuit QED and its controlled light–matter interaction, rather than fold in the full development of superconducting quantum computing. Even with that boundary, the contribution is closely tied to a broad experimental program; optical lattice clocks offer a clearer focused advance in measurement with a mature record of independent realization."
      }
    ],
    "uncertainties": [
      "How the historical record separates Katori's original clock concept from Ye's experimental advances and the subsequent development of optical frequency metrology."
    ],
    "conflict_note": "None apparent from the supplied profile."
  }
}
